 71	export function calculateIncrementalWorkingCapital(input: Array<{
 72	  period: string;
 73	  incrementalRevenue: Decimal.Value;
 74	  incrementalCogs: Decimal.Value;
 75	  dsoDays: Decimal.Value;
 76	  dioDays: Decimal.Value;
 77	  dpoDays: Decimal.Value;
 78	  taxesAndOtherOperating: Decimal.Value;
 79	  daysInPeriod: Decimal.Value;
 80	}>) {
 81	  const periods = input.map((item) => {
 82	    const days = decimal(item.daysInPeriod);
 83	    if (days.lte(0)) throw new RangeError("days in period must be positive");
 84	    const receivables = decimal(item.incrementalRevenue).div(days).mul(item.dsoDays);
 85	    const inventory = decimal(item.incrementalCogs).div(days).mul(item.dioDays);
 86	    const payables = decimal(item.incrementalCogs).div(days).mul(item.dpoDays);
 87	    const requirement = receivables.plus(inventory).minus(payables).plus(item.taxesAndOtherOperating);
 88	    return {
 89	      period: item.period,
 90	      receivables: canonical(receivables),
  1	import Decimal from "decimal.js";
  2	
  3	export type RepaymentFormat = "sac" | "price" | "bullet" | "balloon";
  4	export type InterestConvention = "nominal_annual" | "effective_annual";
  5	export type GraceInterest = "paid" | "capitalized";
  6	
  7	const d = (value: Decimal.Value) => new Decimal(value);
  8	const canonical = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
  9	
 10	export type DebtServiceRow = {
 11	  period: number;
 12	  openingBalance: string;
 13	  interestPaid: string;
 14	  interestCapitalized: string;
 15	  principal: string;
 16	  debtService: string;
 17	  closingBalance: string;
 18	};
 19	
 20	export function periodicRate(input: {annualRate: Decimal.Value; periodsPerYear: number; convention: InterestConvention}) {
 21	  if (!Number.isInteger(input.periodsPerYear) || input.periodsPerYear <= 0) throw new RangeError("periods per year must be a positive integer");
 22	  const annual = d(input.annualRate);
 23	  if (annual.lt(0)) throw new RangeError("annual rate cannot be negative");
 24	  return canonical(input.convention === "nominal_annual"
 25	    ? annual.div(input.periodsPerYear)
 26	    : annual.plus(1).pow(d(1).div(input.periodsPerYear)).minus(1));
 27	}
 28	
 29	export function buildDebtServiceSchedule(input: {
 30	  amount: Decimal.Value;
 31	  annualRate: Decimal.Value;
 32	  rateConvention: InterestConvention;
 33	  termMonths: number;
 34	  graceMonths: number;
 35	  graceInterest: GraceInterest;
 36	  format: RepaymentFormat;
 37	  balloonPercent?: Decimal.Value;
 38	}): {periodicRate: string; rows: DebtServiceRow[]; totalInterest: string; totalDebtService: string; peakDebtService: string; weightedAverageLifeMonths: string} {
 39	  if (!Number.isInteger(input.termMonths) || input.termMonths <= 0) throw new RangeError("term must be a positive integer");
 40	  if (!Number.isInteger(input.graceMonths) || input.graceMonths < 0 || input.graceMonths >= input.termMonths) throw new RangeError("grace must be an integer below term");
 41	  const originalAmount = d(input.amount);
 42	  if (originalAmount.lte(0)) throw new RangeError("amount must be positive");
 43	  const rate = d(periodicRate({annualRate: input.annualRate, periodsPerYear: 12, convention: input.rateConvention}));
 44	  const repaymentPeriods = input.termMonths - input.graceMonths;
 45	  const balloonPercent = input.format === "balloon" ? d(input.balloonPercent ?? -1) : new Decimal(0);
 46	  if (input.format === "balloon" && (balloonPercent.lt(0) || balloonPercent.gt(1))) throw new RangeError("balloon percent must be between zero and one");
 47	
 48	  const rows: DebtServiceRow[] = [];
 49	  let balance = originalAmount;
 50	  let repaymentOpening: Decimal | null = null;
 51	  let totalInterest = new Decimal(0);
 52	  let totalDebtService = new Decimal(0);
 53	  let peakDebtService = new Decimal(0);
 54	  let weightedPrincipalMonths = new Decimal(0);
 55	
 56	  for (let period = 1; period <= input.termMonths; period += 1) {
 57	    const opening = balance;
 58	    const accruedInterest = opening.mul(rate);
 59	    const inGrace = period <= input.graceMonths;
 60	    let interestPaid = inGrace && input.graceInterest === "capitalized" ? new Decimal(0) : accruedInterest;
 61	    const interestCapitalized = inGrace && input.graceInterest === "capitalized" ? accruedInterest : new Decimal(0);
 62	    let principal = new Decimal(0);
 63	    if (inGrace) {
 64	      balance = opening.plus(interestCapitalized);
 65	    } else {
 66	      if (repaymentOpening === null) repaymentOpening = opening;
 67	      const repaymentIndex = period - input.graceMonths;
 68	      const periodsLeft = repaymentPeriods - repaymentIndex + 1;
 69	      if (input.format === "sac") {
 70	        principal = Decimal.min(repaymentOpening.div(repaymentPeriods), opening);
 71	      } else if (input.format === "price") {
 72	        const payment = rate.eq(0)
 73	          ? repaymentOpening.div(repaymentPeriods)
 74	          : repaymentOpening.mul(rate).div(new Decimal(1).minus(new Decimal(1).plus(rate).pow(-repaymentPeriods)));
 75	        principal = Decimal.min(payment.minus(accruedInterest), opening);
 76	      } else if (input.format === "bullet") {
 77	        principal = periodsLeft === 1 ? opening : new Decimal(0);
 78	      } else {
 79	        const balloon = repaymentOpening.mul(balloonPercent);
 80	        const regularPrincipal = repaymentOpening.minus(balloon).div(repaymentPeriods);
 81	        principal = periodsLeft === 1 ? opening : Decimal.min(regularPrincipal, opening);
 82	      }
 83	      if (period === input.termMonths) principal = opening;
 84	      balance = Decimal.max(opening.minus(principal), 0);
 85	    }
 86	    const debtService = interestPaid.plus(principal);
 87	    totalInterest = totalInterest.plus(interestPaid).plus(interestCapitalized);
 88	    totalDebtService = totalDebtService.plus(debtService);
 89	    peakDebtService = Decimal.max(peakDebtService, debtService);
 90	    weightedPrincipalMonths = weightedPrincipalMonths.plus(principal.mul(period));
 91	    rows.push({
 92	      period,
 93	      openingBalance: canonical(opening),
 94	      interestPaid: canonical(interestPaid),
 95	      interestCapitalized: canonical(interestCapitalized),
 96	      principal: canonical(principal),
 97	      debtService: canonical(debtService),
 98	      closingBalance: canonical(balance),
 99	    });
100	  }
101	  return {
102	    periodicRate: canonical(rate),
103	    rows,
104	    totalInterest: canonical(totalInterest),
105	    totalDebtService: canonical(totalDebtService),
106	    peakDebtService: canonical(peakDebtService),
107	    weightedAverageLifeMonths: canonical(weightedPrincipalMonths.div(originalAmount)),
108	  };
109	}
110	
111	export function calculateCoverageSeries(input: {
112	  schedule: readonly DebtServiceRow[];
113	  scenarios: Array<{name: string; cfadsByPeriod: Record<number, Decimal.Value>}>;
114	}) {
115	  return input.scenarios.map((scenario) => {
116	    const periods = input.schedule.map((row) => {
117	      const cfads = scenario.cfadsByPeriod[row.period];
118	      if (cfads === undefined) return {period: row.period, cfads: null, debtService: row.debtService, dscr: null};
119	      const service = d(row.debtService);
120	      return {period: row.period, cfads: canonical(d(cfads)), debtService: row.debtService, dscr: service.gt(0) ? canonical(d(cfads).div(service)) : null};
121	    });
122	    const computable = periods.filter((period): period is typeof period & {dscr: string} => period.dscr !== null);
123	    const minimum = computable.length
124	      ? computable.reduce((lowest, period) => d(period.dscr).lt(lowest.dscr) ? period : lowest)
125	      : null;
126	    return {name: scenario.name, periods, minimumDscr: minimum?.dscr ?? null, criticalPeriod: minimum?.period ?? null};
127	  });
128	}
129	
130	export function calculateCovenantHeadroom(input: {actual: Decimal.Value; limit: Decimal.Value; direction: "maximum" | "minimum"}) {
131	  const actual = d(input.actual);
132	  const limit = d(input.limit);
133	  const absolute = input.direction === "maximum" ? limit.minus(actual) : actual.minus(limit);
134	  const percentage = limit.eq(0) ? null : absolute.div(limit);
135	  return {absolute: canonical(absolute), percentage: percentage === null ? null : canonical(percentage), passes: absolute.gte(0)};
136	}
137	
138	export function maturityConcentration(input: {existing: Record<string, Decimal.Value>; proposed: Record<string, Decimal.Value>}) {
139	  const periods = [...new Set([...Object.keys(input.existing), ...Object.keys(input.proposed)])].sort();
140	  const rows = periods.map((period) => ({
141	    period,
142	    existing: canonical(d(input.existing[period] ?? 0)),
143	    proposed: canonical(d(input.proposed[period] ?? 0)),
144	    consolidated: canonical(d(input.existing[period] ?? 0).plus(input.proposed[period] ?? 0)),
145	  }));
146	  const total = rows.reduce((sum, row) => sum.plus(row.consolidated), new Decimal(0));
147	  return {
148	    rows: rows.map((row) => ({...row, share: total.gt(0) ? canonical(d(row.consolidated).div(total)) : "0"})),
149	    total: canonical(total),
150	    peak: rows.length ? rows.reduce((highest, row) => d(row.consolidated).gt(highest.consolidated) ? row : highest) : null,
151	  };
152	}

